import os
from dataclasses import dataclass
from typing import Any, Dict, Optional

import requests


DEFAULT_OPENAI_BASE_URL = "https://api.openai.com/v1"
DEFAULT_OPENAI_MODEL = "gpt-4.1-mini"


@dataclass(frozen=True)
class StructuredDocumentConfig:
    api_key: Optional[str] = None
    base_url: str = DEFAULT_OPENAI_BASE_URL
    model: str = DEFAULT_OPENAI_MODEL
    timeout: float = 60.0

    @classmethod
    def from_env(cls) -> "StructuredDocumentConfig":
        return cls(
            api_key=os.getenv("OPENAI_API_KEY"),
            base_url=os.getenv("OPENAI_BASE_URL", DEFAULT_OPENAI_BASE_URL),
            model=os.getenv("OPENAI_MODEL", DEFAULT_OPENAI_MODEL),
            timeout=float(os.getenv("OPENAI_TIMEOUT", "60")),
        )


class StructuredDocumentClient:
    def __init__(self, config: Optional[StructuredDocumentConfig] = None) -> None:
        self.config = config or StructuredDocumentConfig.from_env()
        self._session = requests.Session()

    def close(self) -> None:
        self._session.close()

    def extract(self, document_text: str, schema: Dict[str, Any]) -> Dict[str, Any]:
        if not self.config.api_key:
            raise ValueError("OPENAI_API_KEY is required")

        url = self.config.base_url.rstrip("/") + "/responses"
        prompt = (
            "Extract structured data from the provided document text and return only valid JSON "
            "that conforms to the schema. Document text:\n" + document_text
        )
        payload = {
            "model": self.config.model,
            "input": [
                {
                    "role": "system",
                    "content": "You are a structured document extraction assistant.",
                },
                {
                    "role": "user",
                    "content": prompt,
                },
            ],
            "text": {
                "format": {
                    "type": "json_schema",
                    "name": "structured_document_extraction",
                    "schema": schema,
                    "strict": True,
                }
            },
        }
        response = self._session.post(
            url,
            headers={"Authorization": f"Bearer {self.config.api_key}"},
            json=payload,
            timeout=self.config.timeout,
        )
        response.raise_for_status()
        data = response.json()
        return self._extract_json(data)

    @staticmethod
    def _extract_json(response_data: Dict[str, Any]) -> Dict[str, Any]:
        output = response_data.get("output", [])
        for item in output:
            for content in item.get("content", []):
                if content.get("type") in {"output_text", "text"}:
                    text = content.get("text", "")
                    if isinstance(text, str) and text.strip():
                        return __import__("json").loads(text)
        if "output_text" in response_data and response_data["output_text"]:
            return __import__("json").loads(response_data["output_text"])
        raise ValueError("No JSON output found in OpenAI response")


def load_default_client() -> StructuredDocumentClient:
    return StructuredDocumentClient()


def extract_document(document_text: str, schema: Dict[str, Any]) -> Dict[str, Any]:
    client = load_default_client()
    try:
        return client.extract(document_text, schema)
    finally:
        client.close()

import json
import os
from typing import Any, Dict, List, Optional

from openai import OpenAI


DEFAULT_MODEL = "gpt-4o-mini"


def _client() -> OpenAI:
    return OpenAI(api_key=os.environ.get("OPENAI_API_KEY"))


def _as_dict(document: Any) -> Dict[str, Any]:
    if isinstance(document, dict):
        return document
    if isinstance(document, str):
        try:
            parsed = json.loads(document)
        except json.JSONDecodeError:
            return {}
        return parsed if isinstance(parsed, dict) else {}
    return {}


def _required_fields() -> List[str]:
    return ["document_id", "document_type", "issue_date", "confidence_scores"]


def _confidence_scores(document: Dict[str, Any]) -> Dict[str, Any]:
    scores = document.get("confidence_scores")
    return scores if isinstance(scores, dict) else {}


def validate_document_fields(document: Any, min_confidence: float = 0.8) -> Dict[str, Any]:
    payload = _as_dict(document)
    missing_fields = [field for field in _required_fields() if field not in payload or payload[field] in (None, "")]
    confidence_scores = _confidence_scores(payload)
    low_confidence_fields = {
        field: score
        for field, score in confidence_scores.items()
        if isinstance(score, (int, float)) and score < min_confidence
    }
    non_numeric_confidence_fields = {
        field: score
        for field, score in confidence_scores.items()
        if not isinstance(score, (int, float))
    }
    valid = not missing_fields and not low_confidence_fields and not non_numeric_confidence_fields
    return {
        "valid": valid,
        "missing_fields": missing_fields,
        "low_confidence_fields": low_confidence_fields,
        "non_numeric_confidence_fields": non_numeric_confidence_fields,
    }


def validate_document_fields_with_openai(document: Any, min_confidence: float = 0.8) -> Dict[str, Any]:
    payload = _as_dict(document)
    response = _client().responses.create(
        model=DEFAULT_MODEL,
        input=[
            {
                "role": "system",
                "content": "Validate structured document fields and confidence scores.",
            },
            {
                "role": "user",
                "content": json.dumps(
                    {
                        "document": payload,
                        "min_confidence": min_confidence,
                        "required_fields": _required_fields(),
                    }
                ),
            },
        ],
    )
    text = getattr(response, "output_text", "") or ""
    try:
        result = json.loads(text)
    except json.JSONDecodeError:
        result = {}
    if not isinstance(result, dict):
        result = {}
    result.setdefault("provider", "openai")
    result.setdefault("model", DEFAULT_MODEL)
    return result


__all__ = ["validate_document_fields", "validate_document_fields_with_openai"]

